#include <stdio.h>

int kthGrammar(int n, int k) {
    unsigned int x = (unsigned int)(k - 1);
    int parity = 0;
    while (x != 0) {
        parity ^= (int)(x & 1u);
        x >>= 1;
    }
    return parity;
}

